// 벽걸이형만 수집 (링크의 subCategory / productCode / 목록 총 페이지 수)
const TYPES = [
  { type: '벽걸이형', key: 'wall',   subCategory: 'CT50019214', productCode: 'WASRA', total: 229 },
];
const out = [];
for (const t of TYPES) {
  const pages = Math.ceil(t.total / 10) + 1; // 한 페이지 10건, 여유로 +1 (빈 페이지는 자동으로 무시됨)
  for (let p = 1; p <= pages; p++) out.push({ json: { ...t, page: p } });
}
return out;

// 목록 응답 → 글 한 건당 한 행. (유형 정보는 앞 노드에서 같은 순서로 가져옴)
const metas = $('설정 및 페이지 펼치기').all();
const rows = [];
const seen = new Set();
$input.all().forEach((it, i) => {
  const meta = metas[i].json;
  const list = (it.json && it.json.data && it.json.data.listData) || [];
  for (const r of list) {
    const path = String(r.url || '').split('?')[0];
    if (!path) continue;
    const k = meta.key + '|' + path;
    if (seen.has(k)) continue;
    seen.add(k);
    rows.push({ json: {
      key: meta.key, type: meta.type, expected: meta.total,
      cateName: r.cateName || '', sympSubName: r.sympSubName || '', topic: r.topic || '',
      title: r.title || '', date: r.date || '', views: String(r.view || '').replace(/,/g, ''),
      path, fetchUrl: 'https://www.lge.co.kr' + path,
    }});
  }
});
return rows;

// 상세 HTML → 본문 텍스트 → 유형별 CSV(UTF-8 BOM, 엑셀에서 한글 정상 표시)
const metas = $('목록 정리').all();
const pages = $input.all();

function extractView(html) {
  const m = /<div[^>]*class="[^"]*\bview-content\b[^"]*"[^>]*>/i.exec(html);
  if (!m) return '';
  let i = m.index + m[0].length, depth = 1;
  const re = /<(\/?)div\b[^>]*>/gi; re.lastIndex = i;
  let x;
  while ((x = re.exec(html))) {
    depth += x[1] ? -1 : 1;
    if (depth === 0) return html.slice(i, x.index);
  }
  return html.slice(i);
}
function toText(h) {
  return h
    .replace(/<!--[\s\S]*?-->/g, '')
    .replace(/<(style|script|noscript)[\s\S]*?<\/\1>/gi, '')
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<li[^>]*>/gi, '\n- ')
    .replace(/<\/(p|div|tr|h[1-6]|ul|ol|table)>/gi, '\n')
    .replace(/<\/(td|th)>/gi, ' | ')
    .replace(/<[^>]+>/g, '')
    .replace(/&nbsp;/g, ' ').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&#39;/g, "'")
    .replace(/&#(\d+);/g, (_, n) => String.fromCharCode(+n)).replace(/&amp;/g, '&')
    .replace(/[ \t ]+/g, ' ').replace(/ *\n */g, '\n').replace(/\n{3,}/g, '\n\n').trim();
}
const esc = v => '"' + String(v ?? '').replace(/"/g, '""') + '"';
const today = new Date().toISOString().slice(0, 10);
const HEAD = ['제품유형', '중분류', '증상분류', '토픽', '제목', '본문', '작성일', '조회수', '원문URL', '수집일'];

const groups = {};
pages.forEach((p, i) => {
  const m = metas[i].json;
  const raw = typeof p.json.data === 'string' ? p.json.data : '';
  const body = toText(extractView(raw));
  (groups[m.key] = groups[m.key] || { type: m.type, expected: m.expected, rows: [], empty: 0 });
  if (!body) groups[m.key].empty++;
  groups[m.key].rows.push([m.type, m.cateName, m.sympSubName, m.topic, m.title, body, m.date, m.views, 'https://www.lge.co.kr' + m.path, today]);
});

const out = [];
for (const [key, g] of Object.entries(groups)) {
  const csv = '﻿' + [HEAD, ...g.rows].map(r => r.map(esc).join(',')).join('\r\n');
  const fileName = `lg_aircon_${key}.csv`;
  const binary = { data: await this.helpers.prepareBinaryData(Buffer.from(csv, 'utf8'), fileName, 'text/csv') };
  out.push({ json: { fileName, type: g.type, 수집건수: g.rows.length, 목록총건수: g.expected, 본문비어있는건수: g.empty }, binary });
}
return out;
